"""
html_to_pdf.py

Converts an HTML file into a PDF, preserving headings, paragraphs, lists, tables, and inline CSS colors.
Reports any unsupported HTML features that were skipped.

Usage:
    result = html_to_pdf.convert("input.html", "output.pdf")
"""

from html.parser import HTMLParser
from fpdf import FPDF
import re

# ---- HTML Parser ----

class HtmlToPdfParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.elements = []          # list of dicts
        self.skipped_tags = set()
        self._current_tag = None
        self._current_attrs = {}
        self._current_text = []
        self._in_table = False
        self._table_rows = []       # list of list of dicts {type, text}
        self._current_row = []
        self._in_li = False
        self._list_type = None
        self._list_items = []
        self._in_skip = False
        self._skip_depth = 0

        # Tags that we explicitly track for unsupported features
        self.unsupported_tags = {
            'img', 'form', 'script', 'video', 'audio', 'iframe',
            'embed', 'object', 'canvas', 'svg', 'link', 'style'
        }

    def _get_color(self, attrs):
        """Extract inline color from style attribute, return (r,g,b) or None."""
        style = attrs.get('style', '')
        match = re.search(r'color\s*:\s*([^;]+)', style, re.IGNORECASE)
        if match:
            color_str = match.group(1).strip()
            # Try named colors via a small lookup
            named = {
                'red': (255,0,0), 'blue': (0,0,255), 'green': (0,128,0),
                'yellow': (255,255,0), 'white': (255,255,255), 'black': (0,0,0),
                'purple': (128,0,128), 'orange': (255,165,0), 'pink': (255,192,203),
                'brown': (165,42,42), 'gray': (128,128,128), 'grey': (128,128,128),
                'cyan': (0,255,255), 'magenta': (255,0,255)
            }
            color_lower = color_str.lower()
            if color_lower in named:
                return named[color_lower]
            # Try hex #rrggbb or #rgb
            hex_match = re.match(r'^#([0-9a-fA-F]{6}|[0-9a-fA-F]{3})$', color_str)
            if hex_match:
                hex_val = hex_match.group(1)
                if len(hex_val) == 3:
                    hex_val = ''.join([c*2 for c in hex_val])
                r = int(hex_val[0:2], 16)
                g = int(hex_val[2:4], 16)
                b = int(hex_val[4:6], 16)
                return (r, g, b)
            # Try rgb(r,g,b)
            rgb_match = re.match(r'rgb\s*\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*\)', color_str, re.IGNORECASE)
            if rgb_match:
                return (int(rgb_match.group(1)), int(rgb_match.group(2)), int(rgb_match.group(3)))
        return None

    def handle_starttag(self, tag, attrs):
        attrs_dict = dict(attrs)
        tag_lower = tag.lower()

        # Track skipping of unsupported tags
        if tag_lower in self.unsupported_tags:
            self.skipped_tags.add(tag_lower)
            self._in_skip = True
            self._skip_depth = 1
            return
        if self._in_skip:
            self._skip_depth += 1
            return

        if tag_lower in ('h1','h2','h3','h4','h5','h6'):
            self._current_tag = tag_lower
            self._current_attrs = attrs_dict
            self._current_text = []
        elif tag_lower == 'p':
            self._current_tag = 'p'
            self._current_attrs = attrs_dict
            self._current_text = []
        elif tag_lower in ('ul', 'ol'):
            self._list_type = tag_lower
            self._list_items = []
        elif tag_lower == 'li':
            self._in_li = True
            self._current_text = []
        elif tag_lower == 'table':
            self._in_table = True
            self._table_rows = []
        elif tag_lower == 'tr':
            self._current_row = []
        elif tag_lower in ('td', 'th'):
            self._current_tag = 'cell'
            self._current_attrs = attrs_dict
            self._cell_type = tag_lower
            self._current_text = []

    def handle_endtag(self, tag):
        tag_lower = tag.lower()

        # Handle skipping
        if self._in_skip:
            if tag_lower in self.unsupported_tags:
                self._in_skip = False
                self._skip_depth = 0
                return
            self._skip_depth -= 1
            if self._skip_depth == 0:
                self._in_skip = False
            return

        if tag_lower in ('h1','h2','h3','h4','h5','h6'):
            text = ''.join(self._current_text).strip()
            if text:
                color = self._get_color(self._current_attrs)
                self.elements.append({
                    'type': 'heading',
                    'level': int(tag_lower[1]),
                    'text': text,
                    'color': color
                })
            self._current_tag = None
        elif tag_lower == 'p':
            text = ''.join(self._current_text).strip()
            if text:
                color = self._get_color(self._current_attrs)
                self.elements.append({
                    'type': 'paragraph',
                    'text': text,
                    'color': color
                })
            self._current_tag = None
        elif tag_lower == 'li':
            text = ''.join(self._current_text).strip()
            if text:
                self._list_items.append(text)
            self._in_li = False
        elif tag_lower in ('ul', 'ol'):
            if self._list_items:
                self.elements.append({
                    'type': 'list',
                    'list_type': self._list_type,
                    'items': self._list_items
                })
            self._list_type = None
            self._list_items = []
        elif tag_lower == 'table':
            if self._table_rows:
                self.elements.append({
                    'type': 'table',
                    'rows': self._table_rows
                })
            self._in_table = False
            self._table_rows = []
        elif tag_lower == 'tr':
            if self._current_row:
                self._table_rows.append(self._current_row)
            self._current_row = []
        elif tag_lower in ('td', 'th'):
            text = ''.join(self._current_text).strip()
            color = self._get_color(self._current_attrs)
            self._current_row.append({
                'type': self._cell_type,
                'text': text,
                'color': color
            })
            self._current_tag = None

    def handle_data(self, data):
        if self._in_skip:
            return
        if self._current_tag or self._in_li:
            self._current_text.append(data)

# ---- PDF Builder ----

class HtmlToPdfConverter:
    def __init__(self):
        self.pdf = FPDF()
        self.pdf.add_page()
        self.pdf.set_auto_page_break(auto=True, margin=15)
        self.pdf.set_font("Helvetica", size=12)

    def add_heading(self, element):
        level = element['level']
        size = max(12, 24 - 2 * level)
        self.pdf.set_font("Helvetica", 'B', size)
        if element['color']:
            self.pdf.set_text_color(*element['color'])
        else:
            self.pdf.set_text_color(0, 0, 0)
        self.pdf.multi_cell(0, 10, element['text'])
        self.pdf.ln(2)

    def add_paragraph(self, element):
        self.pdf.set_font("Helvetica", size=12)
        if element['color']:
            self.pdf.set_text_color(*element['color'])
        else:
            self.pdf.set_text_color(0, 0, 0)
        self.pdf.multi_cell(0, 7, element['text'])
        self.pdf.ln(2)

    def add_list(self, element):
        self.pdf.set_font("Helvetica", size=12)
        self.pdf.set_text_color(0, 0, 0)
        for idx, item in enumerate(element['items'], start=1):
            if element['list_type'] == 'ul':
                prefix = "  -  "
            else:
                prefix = f"  {idx}. "
            self.pdf.cell(0, 7, prefix + item, new_x="LMARGIN", new_y="NEXT")
        self.pdf.ln(2)

    def add_table(self, element):
        self.pdf.set_font("Helvetica", size=10)
        self.pdf.set_text_color(0, 0, 0)
        rows = element['rows']
        if not rows:
            return
        # Determine column widths
        num_cols = max(len(row) for row in rows) if rows else 1
        page_width = self.pdf.w - 2 * self.pdf.l_margin
        col_width = page_width / num_cols
        # Draw header row with bold
        self.pdf.set_font("Helvetica", 'B', 10)
        for cell in rows[0]:
            self.pdf.cell(col_width, 10, cell['text'], border=1)
        self.pdf.ln()
        # Draw data rows
        self.pdf.set_font("Helvetica", size=10)
        for row in rows[1:]:
            for cell in row:
                if cell['color']:
                    self.pdf.set_text_color(*cell['color'])
                else:
                    self.pdf.set_text_color(0, 0, 0)
                self.pdf.cell(col_width, 10, cell['text'], border=1)
            self.pdf.ln()
        self.pdf.ln(2)

    def add_skipped_section(self, skipped):
        if skipped:
            self.pdf.set_font("Helvetica", 'B', 14)
            self.pdf.set_text_color(100, 0, 0)
            self.pdf.cell(0, 10, "Skipped features:")
            self.pdf.ln()
            self.pdf.set_font("Helvetica", size=10)
            self.pdf.set_text_color(0, 0, 0)
            for tag in sorted(skipped):
                self.pdf.cell(0, 7, f"  - {tag}", new_x="LMARGIN", new_y="NEXT")

def convert(input_html_path: str, output_pdf_path: str) -> dict:
    """
    Convert an HTML file to a PDF.

    Args:
        input_html_path: path to the HTML file
        output_pdf_path: path where the PDF will be written

    Returns:
        dict with keys: 'output_path' (str) and 'skipped_features' (list of str)
    """
    with open(input_html_path, 'r', encoding='utf-8') as f:
        html_content = f.read()

    # Parse
    parser = HtmlToPdfParser()
    parser.feed(html_content)

    # Build PDF
    converter = HtmlToPdfConverter()
    for element in parser.elements:
        if element['type'] == 'heading':
            converter.add_heading(element)
        elif element['type'] == 'paragraph':
            converter.add_paragraph(element)
        elif element['type'] == 'list':
            converter.add_list(element)
        elif element['type'] == 'table':
            converter.add_table(element)

    converter.add_skipped_section(parser.skipped_tags)

    converter.pdf.output(output_pdf_path)

    return {
        'output_path': output_pdf_path,
        'skipped_features': sorted(list(parser.skipped_tags))
    }
